import 'package:material_ui/material_ui.dart';

import '../theme/app_colors.dart';
import '../theme/tokens.dart';

/// Soft, extruded surfaces: every raised thing is the same material as the
/// page, lit from the top left, so it reads as pushed out of the page and a
/// pressed thing reads as pushed in. A 1 px edge keeps every control visible
/// to people who cannot see soft shadows.
///
/// The only texture is a faint paper grain on the page (assets/textures,
/// generated by tool/gen_textures.py).
class Textures {
  Textures._();

  static const paper = 'assets/textures/paper.png';

  /// Starts loading the texture before the first screen, so it does not pop
  /// in. Needs no BuildContext: the image stays in Flutter's image cache.
  static void precache() {
    final stream = AssetImage(paper).resolve(ImageConfiguration.empty);
    late final ImageStreamListener listener;
    void done() => stream.removeListener(listener);
    listener = ImageStreamListener((_, _) => done(), onError: (_, _) => done());
    stream.addListener(listener);
  }

  static DecorationImage image(String asset) => DecorationImage(
    image: AssetImage(asset),
    repeat: ImageRepeat.repeat,
    filterQuality: FilterQuality.medium,
  );
}

/// The one elevation recipe: a dark shadow to the bottom right and a light
/// glow to the top left. [lift] scales both.
List<BoxShadow> raisedShadow(AppColors c, {double lift = 1}) => [
  BoxShadow(
    color: c.highlight,
    blurRadius: 8 * lift,
    offset: Offset(-4 * lift, -4 * lift),
  ),
  BoxShadow(
    color: c.shadow,
    blurRadius: 8 * lift,
    offset: Offset(4 * lift, 4 * lift),
  ),
];

/// The page: one solid colour with a faint paper grain.
BoxDecoration pageDecoration(AppColors c) =>
    BoxDecoration(color: c.background, image: Textures.image(Textures.paper));

/// A raised panel, same material as the page.
BoxDecoration paperDecoration(
  AppColors c, {
  bool tint = false,
  double radius = RohabShape.card,
  bool shadow = true,
}) => BoxDecoration(
  color: tint ? c.accentSoft : c.surface,
  borderRadius: BorderRadius.circular(radius),
  border: Border.all(
    color: tint ? c.accent.withValues(alpha: 0.5) : c.divider,
    width: RohabShape.border,
  ),
  boxShadow: shadow ? raisedShadow(c) : null,
);

/// Paints the finishing touches of a raised surface, or of a pressed one:
/// a thin light edge along the top when raised; a darker face with a dark
/// line along the top when pressed in. It only adds translucent light and
/// shade, so it works over any base colour.
class BevelPainter extends CustomPainter {
  const BevelPainter({
    this.radius = RohabShape.radius,
    this.pressed = false,
    this.flat = false,
  });

  final double radius;

  /// Pushed in: darker, with shade along the top edge.
  final bool pressed;

  /// Disabled: nothing at all.
  final bool flat;

  @override
  void paint(Canvas canvas, Size size) {
    if (flat || size.isEmpty) return;
    canvas.save();
    canvas.clipRRect(
      RRect.fromRectAndRadius(Offset.zero & size, Radius.circular(radius)),
    );
    if (pressed) {
      canvas.drawRect(
        Offset.zero & size,
        Paint()..color = const Color(0x14000000),
      );
      canvas.drawRect(
        Rect.fromLTWH(0, 0, size.width, 3),
        Paint()..color = const Color(0x40000000),
      );
    } else {
      canvas.drawLine(
        Offset(radius * 0.6, 1),
        Offset(size.width - radius * 0.6, 1),
        Paint()
          ..color = const Color(0x55FFFFFF)
          ..strokeWidth = 1.5,
      );
    }
    canvas.restore();
  }

  @override
  bool shouldRepaint(BevelPainter old) =>
      old.radius != radius || old.pressed != pressed || old.flat != flat;
}

/// A raised tile: the base for icon badges and other small non-button
/// controls.
class RaisedTile extends StatelessWidget {
  const RaisedTile({
    super.key,
    required this.color,
    required this.child,
    this.size,
    this.radius = RohabShape.radius,
    this.edge,
  });

  final Color color;
  final Widget child;
  final double? size;
  final double radius;
  final Color? edge;

  @override
  Widget build(BuildContext context) {
    final c = context.colors;
    return Container(
      width: size,
      height: size,
      decoration: BoxDecoration(
        color: color,
        borderRadius: BorderRadius.circular(radius),
        border: Border.all(
          color: edge ?? Color.lerp(color, const Color(0xFF000000), 0.35)!,
          width: 1,
        ),
        boxShadow: raisedShadow(c, lift: 0.5),
      ),
      child: CustomPaint(
        painter: BevelPainter(radius: radius),
        child: Center(child: child),
      ),
    );
  }
}

/// Button look shared by the filled, outlined and text buttons: one flat
/// fill, a 1 px edge, a soft shadow that goes away when pressed, and a
/// darker face while pressed. Disabled: flat, no shadow. The base colour
/// comes from the button's own style.
ButtonStyle raised(ButtonStyle base) {
  return base.copyWith(
    elevation: WidgetStateProperty.resolveWith(
      (s) => s.contains(WidgetState.pressed) || s.contains(WidgetState.disabled)
          ? 0.0
          : 4.0,
    ),
    shadowColor: const WidgetStatePropertyAll(Color(0x665B7691)),
    overlayColor: const WidgetStatePropertyAll(Color(0x00000000)),
    splashFactory: NoSplash.splashFactory,
    backgroundBuilder: (context, states, child) => CustomPaint(
      painter: BevelPainter(
        pressed: states.contains(WidgetState.pressed),
        flat: states.contains(WidgetState.disabled),
      ),
      child: child,
    ),
    foregroundBuilder: (context, states, child) => Transform.translate(
      offset: states.contains(WidgetState.pressed)
          ? const Offset(0, 2)
          : Offset.zero,
      child: child,
    ),
  );
}

/// One option of a choice row (text size, exercise, pain score). The chosen
/// option is pushed in and filled; the others stand out. A check mark joins
/// the chosen label in the screens that use it, so it never relies on colour
/// alone. Put an [InkWell] inside as the [child].
class ChoiceMaterial extends StatelessWidget {
  const ChoiceMaterial({
    super.key,
    required this.selected,
    required this.child,
  });

  final bool selected;
  final Widget child;

  @override
  Widget build(BuildContext context) {
    final c = context.colors;
    const radius = BorderRadius.all(Radius.circular(RohabShape.radius));
    return Material(
      color: selected ? c.accent : c.silver,
      elevation: selected ? 0 : 4,
      shadowColor: const Color(0x665B7691),
      shape: RoundedRectangleBorder(
        borderRadius: radius,
        side: BorderSide(
          color: selected
              ? Color.lerp(c.accent, const Color(0xFF000000), 0.45)!
              : c.silverEdge,
        ),
      ),
      clipBehavior: Clip.antiAlias,
      child: CustomPaint(
        painter: BevelPainter(pressed: selected),
        child: child,
      ),
    );
  }
}
